vec4 convertHSVtoRGB(in float h, in float s, in float v, in float a) {
  float c = v * s;
  h = mod((h * 6.0), 6.0);
  float x = c * (1.0 - abs(mod(h, 2.0) - 1.0));
  vec4 color;

  if (0.0 <= h && h < 1.0) {
    color = vec4(c, x, 0.0, a);
  } else if (1.0 <= h && h < 2.0) {
    color = vec4(x, c, 0.0, a);
  } else if (2.0 <= h && h < 3.0) {
    color = vec4(0.0, c, x, a);
  } else if (3.0 <= h && h < 4.0) {
    color = vec4(0.0, x, c, a);
  } else if (4.0 <= h && h < 5.0) {
    color = vec4(x, 0.0, c, a);
  } else if (5.0 <= h && h < 6.0) {
    color = vec4(c, 0.0, x, a);
  } else {
    color = vec4(0.0, 0.0, 0.0, a);
  }

  color.rgb += v - c;

  return color;
}

float findMin(in float[4] arr, in int size) {
    float tempMin = 999999999.0;
    for (int i = 0; i < size; i++) {
        if (arr[i] < tempMin) {tempMin = arr[i];}
    }
    return tempMin;

}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.yy;
    uv.x += iResolution.y / iResolution.x;
    uv.x -= 1.0;
    uv = uv * 2.0 - vec2(1,1);

    vec2 mouse = iMouse.xy/iResolution.yy;
    mouse.x += iResolution.y / iResolution.x;
    mouse.x -= 1.0;
    mouse = mouse * 2.0 - vec2(1,1);


    vec2 point[4] = vec2[4](uv-mouse, uv+mouse, uv+mouse.yx, uv-mouse.yx);
    float lengths[4] = float[4](0.0,0.0,0.0,0.0);

    float b = 0.0; //calculate brightness
    for (int i = 0; i < 4; i++) {
        lengths[i] = length(point[i]);

        b += 0.5 + 0.5 * sin(100.0*lengths[i] + iTime*1.0);
    }



    float dist = findMin(lengths, 4);
    if (dist < 0.2) {dist = 0.2;}
    b /= dist;
    b /= 10.0;
    //b *= 0.5 + 0.5 * sin(200.0*length(uv - mouse.yx));


    //b *= 0.5 + 0.5 * sin(200.0*length(uv));


    // Output to screen
    fragColor = convertHSVtoRGB(b + 0.6, 1.0, 0.2/dist, 1.0); //vec4(0.0, 0.0, b,1.0);
}
